package org.springframework.samples.petclinic.owner;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;
import java.util.Map;

import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.hasSize;

/**
 * Black-Box API Integration Test.
 *
 * Pure HTTP tests against a real, externally-started server backed by a real MySQL
 * database. No internal application classes are used: only RestAssured HTTP calls, the
 * public {@code /api/auth/login} endpoint for JWT acquisition, and direct JDBC for test
 * data setup/teardown and DB-state verification.
 *
 * @target-controller OwnerRestController
 * (src/main/java/org/springframework/samples/petclinic/owner/OwnerRestController.java)
 * @target-api GET /api/owners/{ownerId}
 *
 * Test-plan checklist cross-check (.nimbus/artifacts/test-plan/OwnerRestController_getOwner.md):
 * - NTC_branch_getOwner_2 (Happy Path, 200) -> covered by NTC_getOwner_withPetAndVisit,
 * NTC_getOwner_withoutPets, NTC_getOwner_boundaryData
 * - ATC_ownerId_noData (DB에 ownerId 조건에 맞는 데이터 없음) -> ATC_ownerId_noData
 * - ATC_code400 (General Bad Request 400) -> ATC_code400
 *
 * VTC-plan cross-check (.nimbus/artifacts/vtc-plan/OwnerRestController_getOwner.md):
 * ownerId is a required @PathVariable Integer, not a form/body parameter, so the generic
 * VTC templates are adapted to path-variable semantics (documented per case below):
 * - VTC_ownerId_NULL / VTC_ownerId_EMPTY: a required path segment has no HTTP-level way to
 * be "null" vs "empty" -- both are implemented as the same well-defined case: a missing
 * path segment (trailing slash), which does not match this handler's route -> 404.
 * - VTC_ownerId_WHITE_SPACE / VTC_ownerId_SPECIAL_CHAR / VTC_ownerId_INVALID_FORMAT /
 * VTC_api_overflow / VTC_api_xss: all become "ownerId fails Integer path-variable
 * conversion" -> Spring's default MethodArgumentTypeMismatchException handling -> 400.
 * - VTC_api_badHeader: adapted to an irrelevant Content-Type header on a body-less GET
 * -> server must ignore it and still return 200.
 * - VTC_api_wrongMethod: adapted to an HTTP method not registered for this exact path
 * pattern (DELETE; only GET and PUT are mapped for /api/owners/{ownerId}) -> 405.
 * - VTC_api_emptyBody / VTC_api_structureTamper: NOT APPLICABLE. GET requests to this
 * endpoint carry no request body, so "empty body" and "tampered body structure" mutations
 * have no meaningful effect distinct from the happy path; per the pipeline's documented
 * fallback for non-applicable mutation cases, these are intentionally not implemented as
 * separate tests.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class OwnerGetOwnerBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/petclinic");

	private static final String DB_USER = System.getProperty("test.db.user", "petclinic");

	private static final String DB_PASSWORD = System.getProperty("test.db.password", "petclinic");

	// Credentials accepted by the public /api/auth/login endpoint
	// (org.springframework.samples.petclinic.security.CustomUserDetailsService).
	private static final String LOGIN_USERNAME = "admin";

	private static final String LOGIN_PASSWORD = "password";

	private static String authToken;

	// 병렬 안전: 각 SQL 실행마다 독립 Connection을 사용
	private static Connection getDbConnection() throws Exception {
		return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
	}

	@BeforeAll
	static void authenticate() {
		authToken = given().baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body(Map.of("username", LOGIN_USERNAME, "password", LOGIN_PASSWORD))
			.when()
			.post("/api/auth/login")
			.then()
			.statusCode(200)
			.extract()
			.path("token");
	}

	/** Deterministic (re-run stable), collision-resistant numeric id derived from a seed. */
	private static int deriveId(String seed) {
		return 700_000_000 + Math.floorMod(seed.hashCode(), 90_000_000);
	}

	private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
		try (Connection conn = getDbConnection();
				InputStream is = OwnerGetOwnerBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath);
				Statement stmt = conn.createStatement()) {
			String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
			for (Map.Entry<String, String> entry : params.entrySet()) {
				sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
			}
			for (String line : sql.split("\n")) {
				String trimmed = line.trim();
				if (trimmed.startsWith("--") || trimmed.isEmpty()) {
					continue;
				}
				if (trimmed.endsWith(";")) {
					trimmed = trimmed.substring(0, trimmed.length() - 1);
				}
				if (!trimmed.isEmpty()) {
					stmt.execute(trimmed);
				}
			}
		}
		catch (Exception e) {
			throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
		}
	}

	/** Fixture parameter set for a given test method: one owner-with-pet-and-visit, one owner-without-pets. */
	private static Map<String, String> fixtureParams(String seed, String ownerFirstName, String ownerLastName,
			String ownerAddress, String ownerCity, String ownerTelephone, String owner2FirstName,
			String owner2LastName, String owner2Address, String owner2City, String owner2Telephone, String petName,
			String petBirthDate, String visitDate, String visitDescription) {
		return Map.ofEntries(Map.entry("OWNER_ID", String.valueOf(deriveId(seed + "#owner"))),
				Map.entry("OWNER_FIRST_NAME", ownerFirstName), Map.entry("OWNER_LAST_NAME", ownerLastName),
				Map.entry("OWNER_ADDRESS", ownerAddress), Map.entry("OWNER_CITY", ownerCity),
				Map.entry("OWNER_TELEPHONE", ownerTelephone),
				Map.entry("OWNER_ID_2", String.valueOf(deriveId(seed + "#owner2"))),
				Map.entry("OWNER_FIRST_NAME_2", owner2FirstName), Map.entry("OWNER_LAST_NAME_2", owner2LastName),
				Map.entry("OWNER_ADDRESS_2", owner2Address), Map.entry("OWNER_CITY_2", owner2City),
				Map.entry("OWNER_TELEPHONE_2", owner2Telephone),
				Map.entry("PET_ID", String.valueOf(deriveId(seed + "#pet"))), Map.entry("PET_NAME", petName),
				Map.entry("PET_BIRTH_DATE", petBirthDate),
				Map.entry("VISIT_ID", String.valueOf(deriveId(seed + "#visit"))),
				Map.entry("VISIT_DATE", visitDate), Map.entry("VISIT_DESCRIPTION", visitDescription));
	}

	// ------------------------------------------------------------------
	// NTC (Happy Path) -- 3 distinct data combinations, DB-state matched
	// with equalTo() only, per the assertion-quality rule.
	// ------------------------------------------------------------------

	@Test
	@DisplayName("NTC_getOwner_withPetAndVisit - owner with one pet and one visit")
	void NTC_getOwner_withPetAndVisit(TestInfo info) {
		String seed = info.getTestMethod().get().getName();
		Map<String, String> p = fixtureParams(seed, "Alice", "Anderson", "1 Test Ave", "Testville", "5551230001",
				"Unused2", "Owner2", "2 Test Ave", "Testville", "5551230002", "Rex", "2020-01-01", "2023-05-10",
				"annual checkup");
		int ownerId = Integer.parseInt(p.get("OWNER_ID"));

		executeSqlTemplate("sql/owner-get-owner-teardown.sql", p);
		executeSqlTemplate("sql/owner-get-owner-setup.sql", p);
		try {
			given().baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
				.pathParam("ownerId", ownerId)
				.log()
				.all()
				.when()
				.get("/api/owners/{ownerId}")
				.then()
				.log()
				.all()
				.statusCode(200)
				.body("id", equalTo(ownerId))
				.body("firstName", equalTo("Alice"))
				.body("lastName", equalTo("Anderson"))
				.body("address", equalTo("1 Test Ave"))
				.body("city", equalTo("Testville"))
				.body("telephone", equalTo("5551230001"))
				.body("pets", hasSize(1))
				.body("pets[0].id", equalTo(Integer.parseInt(p.get("PET_ID"))))
				.body("pets[0].name", equalTo("Rex"))
