	// ------------------------------------------------------------------
	// VTC (RED-parameter mutations, adapted to a required Integer path variable)
	// ------------------------------------------------------------------

	@Test
	@DisplayName("VTC_ownerId_NULL - missing ownerId path segment -> no route match -> 404")
	void VTC_ownerId_NULL() {
		given().baseUri(BASE_URL).header("Authorization", "Bearer " + authToken).log().all().when()
			// trailing slash: the {ownerId} segment is absent, so this does not match
			// GET /api/owners/{ownerId}
			.get("/api/owners/")
			.then()
