	@Test
	@DisplayName("VTC_ownerId_EMPTY - empty ownerId path segment -> no route match -> 404")
	void VTC_ownerId_EMPTY() {
		// Same HTTP-level shape as NULL: a required @PathVariable has no distinct wire
		// representation for "null" vs "empty" (see class-level cross-check note).
		given().baseUri(BASE_URL)
			.header("Authorization", "Bearer " + authToken)
			.log()
			.all()
			.when()
			.get("/api/owners/")
			.then()
			.log()
			.all()
			.statusCode(404);
	}

	@Test
	@DisplayName("VTC_ownerId_WHITE_SPACE - whitespace-only ownerId fails Integer conversion -> 400")
	void VTC_ownerId_WHITE_SPACE() {
		given().baseUri(BASE_URL)
			.header("Authorization", "Bearer " + authToken)
			.pathParam("ownerId", "   ")
			.log()
			.all()
			.when()
			.get("/api/owners/{ownerId}")
			.then()
			.log()
			.all()
			.statusCode(400);
