	@Test
	@DisplayName("VTC_ownerId_SPECIAL_CHAR - SQL-injection-shaped ownerId fails Integer conversion -> 400")
	void VTC_ownerId_SPECIAL_CHAR() {
		given().baseUri(BASE_URL)
			.header("Authorization", "Bearer " + authToken)
			.pathParam("ownerId", "'; DROP TABLE owners --")
			.log()
