	@Test
	@DisplayName("VTC_api_badHeader - irrelevant Content-Type on a body-less GET is ignored -> 200")
	void VTC_api_badHeader(TestInfo info) {
		String seed = info.getTestMethod().get().getName();
		Map<String, String> p = fixtureParams(seed, "Cara", "Chen", "4 Test Ave", "Testville", "5551230006",
				"Unused4", "Owner4", "4 Test Ave", "Testville", "5551230007", "Fido", "2019-06-15", "2022-01-01",
				"checkup");
		int ownerId = Integer.parseInt(p.get("OWNER_ID"));

		executeSqlTemplate("sql/owner-get-owner-teardown.sql", p);
		executeSqlTemplate("sql/owner-get-owner-setup.sql", p);
		try {
			given().baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
				.contentType("application/xml")
				.pathParam("ownerId", ownerId)
				.log()
				.all()
				.when()
				.get("/api/owners/{ownerId}")
				.then()
				.log()
				.all()
				.statusCode(200)
				.body("id", equalTo(ownerId))
				.body("firstName", equalTo("Cara"));
		}
		finally {
			executeSqlTemplate("sql/owner-get-owner-teardown.sql", p);
		}
	}

	@Test
	@DisplayName("VTC_api_wrongMethod - HTTP method not registered for this path -> 405")
	void VTC_api_wrongMethod(TestInfo info) {
		String seed = info.getTestMethod().get().getName();
		int ownerId = deriveId(seed + "#owner");

		// DELETE is not mapped for /api/owners/{ownerId} (only GET and PUT are); no DB
		// fixture is needed since Spring rejects the method before touching the
		// repository.
		given().baseUri(BASE_URL)
			.header("Authorization", "Bearer " + authToken)
			.pathParam("ownerId", ownerId)
			.log()
			.all()
			.when()
			.delete("/api/owners/{ownerId}")
			.then()
			.log()
			.all()
			.statusCode(405);
	}

